/* Local, scripted guidance. Explicit object context travels with a saved plan. */
let guideObject=null;
const guideBox=document.createElement('div');guideBox.className='object-guide';guideBox.hidden=true;$('#chatForm').before(guideBox);
function guideSet(kind,id,label,scope){const discussion=guideObject?.kind===kind&&guideObject.id===id&&pScope(guideObject.scope)===pScope(scope)?guideObject.discussion:'';guideObject={kind,id,label,scope:{topic:scope.topic,start:scope.start,end:scope.end},discussion};guideRender();}
function guideRender(){guideBox.hidden=!guideObject;if(!guideObject)return;guideBox.innerHTML=`<div><button data-guide="open" title="查看当前对象">${guideObject.kind} · ${esc(guideObject.label)}</button><button data-guide="clear" aria-label="取消对话对象">×</button></div><small>${pScope(guideObject.scope)} · 按上方业务和日期讨论</small><nav aria-label="当前对象的提问指引"><button data-guide="focus">哪里值得关注</button><button data-guide="evidence">还缺什么依据</button><button data-guide="plan">下一步怎么做</button></nav>`;}
const guideSem=semDepthOpen;semDepthOpen=function(id,scope=pSnapshot(),tab='summary'){guideSem(id,scope,tab);const r=semDepthKeywords(scope).find(x=>x.id===id);if(r)guideSet('SEM',id,r.title,scope);};
const guideSeo=seoOpen;seoOpen=function(id,scope=pSnapshot(),tab='overview'){guideSeo(id,scope,tab);const r=panoramaData.content.find(x=>x.id===id);if(r)guideSet('SEO',id,r.title,scope);};
const guideGeo=geoOpen;geoOpen=function(q,engine,scope=pSnapshot()){guideGeo(q,engine,scope);guideSet('GEO',`GQ-${geoQuestions.indexOf(q)+1}-${geoEngines.indexOf(engine)+1}`,q+' / '+engine,scope);};
function guideOpen(g){if(g.kind==='SEM')semDepthOpen(g.id,g.scope);else if(g.kind==='SEO')seoOpen(g.id,g.scope);else{const [,q,en]=g.id.split('-');geoOpen(geoQuestions[Number(q)-1],geoEngines[Number(en)-1],g.scope);}}
function guideFacts(g){
 if(g.kind==='SEM'){const r=semDepthKeywords(g.scope).find(x=>x.id===g.id);return {facts:`演示花费 ${money(r.cost)}，${r.clicks} 次点击、${r.conversions} 次报表转化。`,gap:'需要核实转化有效性、重复记录与追踪覆盖。点击和花费不能证明获客质量。',action:'核实关键词转化',owner:'客户运营负责人',criterion:'逐条记录核实结论与来源；无法确认的保留待补充依据，核实完成与获客效果分别验收。'};}
 if(g.kind==='SEO'){const r=panoramaData.content.find(x=>x.id===g.id);return {facts:`内容状态：${r.status}；负责人：${r.owner}。`,gap:r.status==='已发布'?'还需确认页面是否正常打开、搜索引擎是否已收录，以及这篇文章带来了多少访问。':'先补齐业务事实、案例来源和审核意见；尚未确认发布与页面效果。',action:seoNext(r),owner:r.owner,criterion:'逐项记录审核或复查结果与依据。发布、页面能否正常打开和搜索效果分别确认，缺失项保留待补充。'};}
 const [,q,en]=g.id.split('-'),r=geoCell(geoQuestions[Number(q)-1],geoEngines[Number(en)-1],g.scope);return {facts:`当前观测：${geoStatus(r)}；正式品牌表现评分未生成。`,gap:'需要真实回答、引用、AI 模型版本和回答获取时间。模拟记录不能作为首次真实记录，也不能证明内容不足。',action:'获取真实回答，再检查变化',owner:'品牌运营负责人',criterion:'保留真实回答、时间、模型和引用；固定问题与引擎比较，条件不同注明不可比。回答收集完成与品牌表现变化分别验收。'};
}
function guidePlan(g){const f=guideFacts(g);closeDialog();pChange(g.scope);pPlan(g.kind==='SEM'?'verify':g.kind==='SEO'?'content':'geo',g.id);const form=$('#pPlanForm');form.elements.title.value=f.action+'：'+g.label;form.elements.owner.value=f.owner;form.elements.note.value=`${g.kind} / ${g.id} / ${g.label}。${pScope(g.scope)}。${f.facts} ${f.gap} 本地原型方案，尚未交给负责人。`;form.elements.criterion.value=f.criterion;}
function guideAnswer(action,question){if(!guideObject)return;closeDialog();showChat();const g=guideObject,f=guideFacts(g),text=action==='focus'?f.facts+' '+f.gap:action==='evidence'?f.gap:'建议：'+f.action+'。'+f.criterion;g.discussion=text;addMessage('user',question);addMessage('assistant',`<p><strong>${esc(g.label)}</strong></p><p>${esc(text)}</p><p>${pScope(g.scope)} · 演示回答</p><button class="seo-entry" data-guide="confirm" data-guide-context="${esc(JSON.stringify(g))}">查看并修改行动方案</button>`);}
const guideReply=reply;reply=function(q){if(guideObject&&/^(处理一下|帮我处理一下|安排一下|下一步怎么做|哪里值得关注|还缺什么依据)[？?。！!\s]*$/.test(q.trim())){guideAnswer(/关注/.test(q)?'focus':/依据/.test(q)?'evidence':'plan',q);if(/处理一下|安排一下/.test(q))guidePlan(guideObject);return;}guideReply(q);};
function guideCapture(object,scope){if(!guideObject||guideObject.id!==object||pScope(guideObject.scope)!==pScope(scope))return null;return JSON.parse(JSON.stringify({...guideObject,discussion:guideObject.discussion||guideFacts(guideObject).facts+' '+guideFacts(guideObject).gap}));}
const guideTask=showTask;showTask=function(id){guideTask(id);const t=localDrafts.find(x=>x.id===id),g=t?.sourcePano?.guidance;if(!g)return;$('#dialogBody').insertAdjacentHTML('beforeend',`<section class="guide-task"><h3>返回这项行动的起点</h3><p>${esc(g.label)} · ${pScope(g.scope)}</p><div class="guide-status"><span>${t.status==='cancelled'?'已撤回':'已保存 · 尚未交给负责人'}</span><span>执行完成：未确认</span><span>效果核实：未确认</span></div><button data-guide-task="${esc(id)}" data-guide-destination="object">返回这条数据</button><button data-guide-task="${esc(id)}" data-guide-destination="discussion">查看当时讨论</button></section>`);};
window.addEventListener('click',e=>{const b=e.target.closest('[data-guide],[data-guide-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.guideTask){const g=localDrafts.find(x=>x.id===b.dataset.guideTask)?.sourcePano?.guidance;if(!g)return;closeDialog();guideObject=JSON.parse(JSON.stringify(g));guideRender();if(b.dataset.guideDestination==='object'){guideOpen(g);return;}showChat();addMessage('assistant',`<p><strong>行动创建时的讨论记录</strong> · ${esc(g.label)}</p><p>${esc(g.discussion)}</p><p>${pScope(g.scope)} · 保存时的原型判断，不是最新执行结果。</p>`);return;}if(b.dataset.guide==='clear'){guideObject=null;guideRender();return;}if(!guideObject&&b.dataset.guide!=='confirm')return;if(b.dataset.guide==='open'){guideOpen(guideObject);return;}if(b.dataset.guide==='confirm'){guideObject=JSON.parse(b.dataset.guideContext);guideRender();guidePlan(guideObject);return;}guideAnswer(b.dataset.guide,b.textContent);},true);

const guideReset=resetChat;resetChat=function(...args){guideObject=null;guideRender();return guideReset(...args);};
